/** Encoding agent-supplied JSON: not_found for an unknown capability, member or message. */
export type Encoded = { ok: true; value: Uint8Array } | { ok: false; error: 'not_found' | 'invalid_args'; detail: string };

/** A field as the JSON accessors see it: how its JSON form maps to the typed value, and what they check. */
export interface JsonField {
  readonly name: string;
  /** JSON forms that differ from the typed value: hex bytes, decimal u64, nested messages. */
  readonly json?: 'bytes' | 'u64' | readonly JsonField[];
  /** Enum members; other values decode (enums are open) but the JSON accessors reject them. */
  readonly members?: Readonly<Record<string, number>>;
  /** The YAML range, checked by the JSON accessors (as C++ dispatch does), not by the codec. */
  readonly range?: readonly [number, number];
  /** An implicit field whose range excludes 0: zero is the absent field and passes (design c2 §3). */
  readonly zeroExempt?: true;
}

/** A typed codec plus the field table its JSON form needs. */
export interface Codec<T> {
  readonly fields: readonly JsonField[];
  /** Worst-case encoded size of any value the field types can carry. */
  readonly maxSize: number;
  encode(value: Partial<T>): Uint8Array;
  decode(bytes: Uint8Array): Decoded<T>;
}

export type MemberPart = 'args' | 'result' | 'event' | 'state';

