export const EMPTY = new Uint8Array(0);

const utf8 = new TextEncoder();

function show(v: unknown): string {
  if (typeof v === 'bigint') {
    return v.toString() + 'n';
  }
  if (v instanceof Uint8Array) {
    return 'Uint8Array(' + v.length + ')';
  }
  if (typeof v === 'string') {
    return JSON.stringify(v);
  }
  if (typeof v === 'object' && v !== null) {
    return Array.isArray(v) ? 'an array' : 'an object';
  }
  return String(v);
}

function bad(name: string, expected: string, v: unknown): never {
  throw new RangeError(name + ': expected ' + expected + ', got ' + show(v));
}

// ---- typed encoder checks (the field type; ranges are the JSON accessors' job) ----

export function int(v: unknown, min: number, max: number, name: string): number {
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    bad(name, 'an integer in [' + min + ', ' + max + ']', v);
  }
  return v;
}

export function u64(v: unknown, min: bigint, max: bigint, name: string): bigint {
  if (typeof v !== 'bigint' || v < min || v > max) {
    bad(name, 'a bigint in [' + min + ', ' + max + ']', v);
  }
  return v;
}

export function f32(v: unknown, name: string): number {
  if (typeof v !== 'number') {
    bad(name, 'a number', v);
  }
  return v;
}

export function bool(v: unknown, name: string): boolean {
  if (typeof v !== 'boolean') {
    bad(name, 'a boolean', v);
  }
  return v;
}

/** The string's UTF-8 bytes; max counts bytes, not characters. */
export function str(v: unknown, max: number, name: string): Uint8Array {
  if (typeof v !== 'string') {
    bad(name, 'a string', v);
  }
  const b = utf8.encode(v);
  if (b.length > max) {
    throw new RangeError(name + ': ' + b.length + ' UTF-8 bytes, max ' + max);
  }
  return b;
}

export function bytes(v: unknown, max: number, name: string): Uint8Array {
  if (!(v instanceof Uint8Array)) {
    bad(name, 'a Uint8Array', v);
  }
  if (v.length > max) {
    throw new RangeError(name + ': ' + v.length + ' bytes, max ' + max);
  }
  return v;
}

/** A serial layout's mac: exactly 6 bytes; absent is six zero bytes. */
export function mac(v: unknown, name: string): Uint8Array {
  if (v === undefined) {
    return new Uint8Array(6);
  }
  if (!(v instanceof Uint8Array) || v.length !== 6) {
    bad(name, '6 bytes', v);
  }
  return v;
}

export function list(v: unknown, max: number, name: string): readonly unknown[] {
  if (!Array.isArray(v)) {
    bad(name, 'an array', v);
  }
  if (v.length > max) {
    throw new RangeError(name + ': ' + v.length + ' items, max ' + max);
  }
  return v;
}

export function obj(v: unknown, name: string): Record<string, unknown> {
  if (typeof v !== 'object' || v === null || Array.isArray(v) || v instanceof Uint8Array) {
    bad(name, 'an object', v);
  }
  return v as Record<string, unknown>;
}

/** A member name, or any number of the underlying type (enums are open; the JSON form takes names only). */
export function enumValue(table: Readonly<Record<string, number>>, v: unknown, name: string, max: number): number {
  if (typeof v === 'string' && Object.hasOwn(table, v)) {
    return table[v];
  }
  if (typeof v === 'number' && Number.isInteger(v) && v >= 0 && v <= max) {
    return v;
  }
  return bad(name, 'one of ' + Object.keys(table).join(', ') + ' or an integer in [0, ' + max + ']', v);
}

// ---- decode helpers (errors stick to the reader, as in the runtime) ----

export function enumNames<T extends string>(table: Readonly<Record<T, number>>): ReadonlyMap<number, T> {
  return new Map(Object.entries(table as Readonly<Record<string, number>>).map(([k, n]) => [n, k as T]));
}

/** The member name, or the number for a value the schema does not name. */
export function readEnum<T extends string>(r: Reader, names: ReadonlyMap<number, T>, max: number): T | number {
  const v = r.readUint(max);
  return names.get(v) ?? v;
}

export function rawEnum<T extends string>(r: Reader, names: ReadonlyMap<number, T>, max: number): T | number {
  const v = r.rawUint(max);
  return names.get(v) ?? v;
}

/**
 * Packed scalars in one length-delimited field; a repeated occurrence replaces the earlier one (last
 * wins). Element max+1 is too_long, reported before it is read.
 */
export function readPacked<T>(r: Reader, max: number, element: (p: Reader) => T): T[] {
  const p = r.readSub();
  const out: T[] = [];
  while (p.ok && !p.atEnd) {
    if (out.length === max) {
      p.fail('too_long');
      break;
    }
    const e = element(p);
    if (p.ok) {
      out.push(e);
    }
  }
  r.adopt(p);
  return out;
}

/** One element of a repeated message field (occurrences append); occurrence max+1 is too_long before it is read. */
export function readRepeated<T>(r: Reader, out: T[], max: number, element: (p: Reader) => T): void {
  if (out.length === max) {
    r.fail('too_long');
    return;
  }
  const p = r.readSub();
  if (!r.ok) {
    return;
  }
  const e = element(p);
  if (r.adopt(p)) {
    out.push(e);
  }
}

/** One nested message field (design m2-c5-display D2): the last occurrence wins; a malformed one fails the reader. */
export function readNested<T>(r: Reader, element: (p: Reader) => T, prev: T): T {
  const p = r.readSub();
  if (!r.ok) {
    return prev;
  }
  const e = element(p);
  return r.adopt(p) ? e : prev;
}

export function done<T>(r: Reader, value: T): Decoded<T> {
  return r.error === null ? decodeOk(value) : decodeFail(r.error);
}

export function decodeEmpty(bytes: Uint8Array): Decoded<Record<string, never>> {
  const r = new Reader(bytes);
  while (r.next()) {
    r.skip();
  }
  return done(r, {});
}

/** Commands without fields, and the RESULT of commands that declare none. */
export const EMPTY_CODEC: Codec<Record<string, never>> = { fields: [], maxSize: 0, encode: () => new Uint8Array(0), decode: decodeEmpty };

// ---- JSON form ----

const HEX = '0123456789abcdef';

export function toHex(b: Uint8Array): string {
  let s = '';
  for (const x of b) {
    s += HEX[x >> 4] + HEX[x & 15];
  }
  return s;
}

export function fromHex(s: string, name: string): Uint8Array {
  if (!/^([0-9a-fA-F]{2})*$/.test(s)) {
    bad(name, 'an even-length hex string', s);
  }
  const out = new Uint8Array(s.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(s.slice(2 * i, 2 * i + 2), 16);
  }
  return out;
}

function fromJsonValue(f: JsonField, v: unknown, name: string, lenient: boolean): unknown {
  if (f.members && !(lenient && typeof v === 'number')) {
    // The JSON Schema form, as C++ diag_json takes it: member names only.
    if (typeof v !== 'string' || !Object.hasOwn(f.members, v)) {
      bad(name, 'one of ' + Object.keys(f.members).join(', '), v);
    }
    return v;
  }
  if (f.json === 'bytes') {
    return typeof v === 'string' ? fromHex(v, name) : v;
  }
  if (f.json === 'u64') {
    if (typeof v === 'string' && /^[0-9]{1,20}$/.test(v)) {
      return BigInt(v);
    }
    return typeof v === 'number' && Number.isSafeInteger(v) ? BigInt(v) : v;
  }
  if (typeof f.json === 'object') {
    return fromJson(f.json, v, name, lenient);
  }
  return v;
}

/**
 * JSON form -> typed input: hex strings to bytes, decimal strings to u64, nested messages recursively.
 * As the JSON Schemas and C++ diag_json have it, enums are member names and a field is either a value or
 * left out: null throws RangeError (an undefined value or a null/undefined top-level value is absent), as
 * do unknown keys. lenient also takes an enum member as any number of its type (encodeJson(…, false)).
 * Other types are left to the typed encoder.
 */
export function fromJson(fields: readonly JsonField[], value: unknown, path = '', lenient = false): Record<string, unknown> {
  if (value === undefined || (value === null && path === '')) {
    return {};
  }
  const o = obj(value, path || 'value');
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(o)) {
    const f = fields.find((x) => x.name === k);
    const name = path ? path + '.' + k : k;
    if (!f) {
      throw new RangeError(name + ': unknown field (' + (fields.length > 0 ? 'fields: ' + fields.map((x) => x.name).join(', ') : 'no fields') + ')');
    }
    if (v === undefined) {
      continue;
    }
    if (v === null) {
      throw new RangeError(name + ': null is not a value (leave the field out)');
    }
    out[k] = Array.isArray(v) ? v.map((x, i) => fromJsonValue(f, x, name + '[' + i + ']', lenient)) : fromJsonValue(f, v, name, lenient);
  }
  return out;
}

/** Typed value -> JSON form (bytes as lowercase hex, bigint as a decimal string). */
export function toJson(v: unknown): unknown {
  if (v instanceof Uint8Array) {
    return toHex(v);
  }
  if (typeof v === 'bigint') {
    return v.toString();
  }
  if (Array.isArray(v)) {
    return v.map(toJson);
  }
  if (typeof v === 'object' && v !== null) {
    const out: Record<string, unknown> = {};
    for (const [k, x] of Object.entries(v)) {
      out[k] = toJson(x);
    }
    return out;
  }
  return v;
}

/**
 * The first 'range' or enum-membership violation in a typed value, or null; C++ valid() checks the same.
 * A NaN is outside every range; a zeroExempt field at 0 (an f32 -0 too, as in C++) is the absent field.
 */
export function invalid(fields: readonly JsonField[], value: Record<string, unknown>, path = ''): string | null {
  for (const f of fields) {
    const v = value[f.name];
    const name = path ? path + '.' + f.name : f.name;
    if (v === undefined) {
      continue;
    }
    if (typeof f.json === 'object') {
      // A repeated message (array) or one nested message.
      if (!Array.isArray(v)) {
        const p = invalid(f.json, v as Record<string, unknown>, name);
        if (p !== null) {
          return p;
        }
        continue;
      }
      const items = v as Record<string, unknown>[];
      for (let i = 0; i < items.length; i++) {
        const p = invalid(f.json, items[i], name + '[' + i + ']');
        if (p !== null) {
          return p;
        }
      }
      continue;
    }
    if (f.members) {
      const known = Object.values(f.members);
      const items = Array.isArray(v) ? v : [v];
      for (const x of items) {
        if (typeof x === 'number' && !known.includes(x)) {
          return name + ': ' + x + ' is not one of ' + Object.keys(f.members).join(', ');
        }
      }
    }
    if (f.range && (typeof v === 'number' || typeof v === 'bigint') && !(f.zeroExempt && (v === 0 || v === 0n)) && !(v >= f.range[0] && v <= f.range[1])) {
      return name + ': ' + v + ' is outside [' + f.range[0] + ', ' + f.range[1] + ']';
    }
  }
  return null;
}

/**
 * JSON form -> bytes. With validate (the default) the value as the receiver decodes it, defaults
 * applied, must keep every field in range and every enum value named, which is what C++ dispatch
 * checks (invalid_args); the codec itself carries both.
 */
export function encodeJson(codec: Codec<any>, value: unknown, validate = true): Encoded {
  try {
    const bytes = codec.encode(fromJson(codec.fields, value, '', !validate));
    if (validate) {
      const back = codec.decode(bytes);
      const problem = back.ok ? invalid(codec.fields, back.value) : back.error;
      if (problem !== null) {
        return { ok: false, error: 'invalid_args', detail: problem };
      }
    }
    return { ok: true, value: bytes };
  } catch (e) {
    if (e instanceof RangeError) {
      return { ok: false, error: 'invalid_args', detail: e.message };
    }
    throw e;
  }
}

/** Bytes -> JSON form. With validate (the default) a range or enum violation, defaults included, is out_of_range. */
export function decodeJson(codec: Codec<any>, bytes: Uint8Array, validate = true): Decoded<Record<string, unknown>> {
  const d = codec.decode(bytes);
  if (!d.ok) {
    return d;
  }
  if (validate && invalid(codec.fields, d.value) !== null) {
    return decodeFail('out_of_range');
  }
  return decodeOk(toJson(d.value) as Record<string, unknown>);
}

export function notFound(what: string): Encoded {
  return { ok: false, error: 'not_found', detail: what + ' not found' };
}

// ---- lookup ----

export function lookupCap(caps: readonly CapInfo[], cap: number | string): CapInfo | undefined {
  return caps.find((c) => (typeof cap === 'number' ? c.id === cap : c.name === cap));
}

export function lookupMember(caps: readonly CapInfo[], cap: number | string, part: MemberPart, member: number | string): MemberRef | undefined {
  const c = lookupCap(caps, cap);
  if (!c) {
    return undefined;
  }
  const match = (m: { id: number; name: string }) => (typeof member === 'number' ? m.id === member : m.name === member);
  if (part === 'args' || part === 'result') {
    const cmd = c.commands.find(match);
    return cmd ? { cap: c, part, id: cmd.id, name: cmd.name, codec: part === 'args' ? cmd.args : (cmd.result ?? EMPTY_CODEC) } : undefined;
  }
  if (part === 'event') {
    const ev = c.events.find(match);
    return ev ? { cap: c, part, id: ev.id, name: ev.name, codec: ev.codec } : undefined;
  }
  if (part === 'state') {
    const p = c.properties.find(match);
    return p ? { cap: c, part, id: p.id, name: p.name, codec: p.codec } : undefined;
  }
  return undefined;
}
